from datetime import timedelta

from django.db import migrations, models

# Status labels found in old status changes ("Nou → Sunat"); any other one was an open status.
CLOSED_LABELS = {
    "Câștigat": "castigata",
    "Câștigată": "castigata",
    "Pierdut": "pierduta",
    "Pierdută": "pierduta",
}


def split_status_comments(apps, schema_editor):
    """A status change becomes its own history entry, marked with the status it led to;
    the comment written with it becomes an ordinary note just before it."""
    Note = apps.get_model("oportunitati", "Note")
    for change in Note.objects.exclude(status_change=""):
        label = change.status_change.split("→")[-1].split("·")[0].strip()
        change.new_status = CLOSED_LABELS.get(label, "potential")
        if change.text:
            note = Note.objects.create(
                opportunity_id=change.opportunity_id, author_id=change.author_id, text=change.text
            )
            Note.objects.filter(pk=note.pk).update(
                created_at=change.created_at - timedelta(milliseconds=1)
            )
            change.text = ""
        change.save(update_fields=["new_status", "text"])


